import fs from 'node:fs/promises';
import fsSync from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export const DEFAULT_DATA_PATH = path.resolve(process.cwd(), 'books.json');

export class BookStore {
  constructor(filePath = process.env.BOOKS_FILE || DEFAULT_DATA_PATH) {
    this.filePath = path.resolve(filePath);
    this._writeQueue = Promise.resolve();
  }

  _ensureFileSync() {
    const dir = path.dirname(this.filePath);
    if (!fsSync.existsSync(dir)) {
      fsSync.mkdirSync(dir, { recursive: true });
    }
    if (!fsSync.existsSync(this.filePath)) {
      fsSync.writeFileSync(this.filePath, JSON.stringify([], null, 2), 'utf8');
    }
  }

  async _readRaw() {
    this._ensureFileSync();
    try {
      const content = await fs.readFile(this.filePath, 'utf8');
      if (!content.trim()) return [];
      const parsed = JSON.parse(content);
      if (Array.isArray(parsed)) return parsed;
      if (parsed && Array.isArray(parsed.books)) return parsed.books;
      return [];
    } catch (err) {
      if (err.code === 'ENOENT') {
        await this._writeRaw([]);
        return [];
      }
      throw err;
    }
  }

  async _writeRaw(books) {
    const dir = path.dirname(this.filePath);
    await fs.mkdir(dir, { recursive: true });
    const data = JSON.stringify(books, null, 2);
    await fs.writeFile(this.filePath, data, 'utf8');
  }

  _enqueue(operation) {
    const next = this._writeQueue.then(operation, operation);
    this._writeQueue = next.catch(() => {});
    return next;
  }

  async getAllBooks() {
    return this._readRaw();
  }

  async getBookById(id) {
    const books = await this._readRaw();
    return books.find((b) => String(b.id) === String(id)) || null;
  }

  async addBook({ title, author, notes = '', status = 'reading' }) {
    const cleanTitle = typeof title === 'string' ? title.trim() : '';
    const cleanAuthor = typeof author === 'string' ? author.trim() : '';
    const cleanNotes = typeof notes === 'string' ? notes.trim() : '';
    const normalizedStatus =
      status === 'finished' || status === true ? 'finished' : 'reading';

    if (!cleanTitle) {
      const error = new Error('Title is required');
      error.statusCode = 400;
      throw error;
    }
    if (!cleanAuthor) {
      const error = new Error('Author is required');
      error.statusCode = 400;
      throw error;
    }

    return this._enqueue(async () => {
      const books = await this._readRaw();
      const now = new Date().toISOString();
      const book = {
        id: crypto.randomUUID(),
        title: cleanTitle,
        author: cleanAuthor,
        notes: cleanNotes,
        status: normalizedStatus,
        finished: normalizedStatus === 'finished',
        createdAt: now,
        updatedAt: now,
        finishedAt: normalizedStatus === 'finished' ? now : null,
      };
      books.push(book);
      await this._writeRaw(books);
      return book;
    });
  }

  async updateBook(id, updates = {}) {
    return this._enqueue(async () => {
      const books = await this._readRaw();
      const index = books.findIndex((b) => String(b.id) === String(id));
      if (index === -1) {
        return null;
      }

      const existing = books[index];
      const updated = { ...existing };

      if (updates.title !== undefined) {
        const cleanTitle = String(updates.title).trim();
        if (!cleanTitle) {
          const error = new Error('Title cannot be empty');
          error.statusCode = 400;
          throw error;
        }
        updated.title = cleanTitle;
      }

      if (updates.author !== undefined) {
        const cleanAuthor = String(updates.author).trim();
        if (!cleanAuthor) {
          const error = new Error('Author cannot be empty');
          error.statusCode = 400;
          throw error;
        }
        updated.author = cleanAuthor;
      }

      if (updates.notes !== undefined) {
        updated.notes = String(updates.notes).trim();
      }

      if (updates.status !== undefined || updates.finished !== undefined) {
        const isFinished =
          updates.status === 'finished' ||
          updates.finished === true ||
          updates.finished === 'true';
        updated.status = isFinished ? 'finished' : 'reading';
        updated.finished = isFinished;
        updated.finishedAt = isFinished
          ? existing.finishedAt || new Date().toISOString()
          : null;
      }

      updated.updatedAt = new Date().toISOString();
      books[index] = updated;
      await this._writeRaw(books);
      return updated;
    });
  }

  async markAsFinished(id) {
    return this.updateBook(id, { status: 'finished', finished: true });
  }

  async deleteBook(id) {
    return this._enqueue(async () => {
      const books = await this._readRaw();
      const index = books.findIndex((b) => String(b.id) === String(id));
      if (index === -1) return false;
      books.splice(index, 1);
      await this._writeRaw(books);
      return true;
    });
  }
}

