}

function renderBookItem(book) {
  const isFinished = book.status === 'finished' || book.finished === true;
  const bookUrl = `/books/${encodeURIComponent(book.id)}`;
  return `<li class="book-item" data-book-id="${escapeHtml(book.id)}" data-status="${isFinished ? 'finished' : 'reading'}">
    <div class="book-info">
      <a href="${bookUrl}" class="book-title-link">${escapeHtml(book.title)}</a>
      <div class="book-author">by ${escapeHtml(book.author)}</div>
      ${
        book.notes
          ? `<p class="book-notes-preview">${escapeHtml(book.notes)}</p>`
          : ''
      }
    </div>
    <div class="book-actions">
      <span class="status-badge ${isFinished ? 'status-finished' : 'status-reading'}">
        ${isFinished ? 'Finished' : 'Currently Reading'}
      </span>
      ${
        !isFinished
          ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" class="finish-form" data-book-id="${escapeHtml(book.id)}" style="margin:0;">
              <button type="submit" class="btn btn-secondary finish-btn" data-book-id="${escapeHtml(book.id)}">Mark as Finished</button>
            </form>`
          : ''
      }
      <a href="${bookUrl}" class="btn btn-secondary">View</a>
    </div>
  </li>`;
}

function renderHomePage(books) {
  const currentlyReading = books.filter(
    (b) => b.status !== 'finished' && b.finished !== true
  );
  const finishedBooks = books.filter(
    (b) => b.status === 'finished' || b.finished === true
  );

  const content = `
    <section class="card" aria-labelledby="add-book-heading">
      <h2 id="add-book-heading">Add a Book</h2>
      <form id="add-book-form" method="POST" action="/books">
        <div class="form-grid">
          <div class="form-group">
            <label for="title">Title</label>
            <input type="text" id="title" name="title" required placeholder="e.g. The Left Hand of Darkness" />
          </div>
          <div class="form-group">
            <label for="author">Author</label>
            <input type="text" id="author" name="author" required placeholder="e.g. Ursula K. Le Guin" />
          </div>
          <div class="form-group full">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" placeholder="Thoughts, favorite quotes, or chapter notes..."></textarea>
          </div>
        </div>
        <button type="submit" class="btn btn-primary">Add Book</button>
      </form>
    </section>

    <section class="card" id="currently-reading-section" aria-labelledby="currently-reading-heading">
      <div class="section-header">
        <h2 id="currently-reading-heading" style="margin:0;">Currently Reading</h2>
        <span class="count-badge" id="reading-count">${currentlyReading.length}</span>
      </div>
      ${
        currentlyReading.length > 0
          ? `<ul class="book-list" id="currently-reading-list">${currentlyReading.map(renderBookItem).join('')}</ul>`
          : `<p class="empty-state" id="currently-reading-empty">No books currently being read.</p><ul class="book-list" id="currently-reading-list"></ul>`
      }
    </section>

    <section class="card" id="finished-section" aria-labelledby="finished-heading">
      <div class="section-header">
        <h2 id="finished-heading" style="margin:0;">Finished</h2>
        <span class="count-badge" id="finished-count">${finishedBooks.length}</span>
      </div>
      ${
        finishedBooks.length > 0
          ? `<ul class="book-list" id="finished-list">${finishedBooks.map(renderBookItem).join('')}</ul>`
          : `<p class="empty-state" id="finished-empty">No finished books yet.</p><ul class="book-list" id="finished-list"></ul>`
      }
    </section>

    <script>
      (function() {
        const addForm = document.getElementById('add-book-form');
        if (addForm) {
          addForm.addEventListener('submit', async function(e) {
            if (!window.fetch) return;
            e.preventDefault();
            const formData = new FormData(addForm);
            const payload = {
              title: formData.get('title'),
              author: formData.get('author'),
              notes: formData.get('notes') || ''
            };
            const res = await fetch('/api/books', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
              body: JSON.stringify(payload)
            });
            if (res.ok) {
              window.location.reload();
            }
          });
        }

        document.addEventListener('submit', async function(e) {
          const form = e.target.closest('.finish-form');
          if (!form || !window.fetch) return;
          e.preventDefault();
          const bookId = form.getAttribute('data-book-id');
          if (!bookId) return;
          const res = await fetch('/api/books/' + encodeURIComponent(bookId) + '/finish', {
            method: 'POST',
            headers: { 'Accept': 'application/json' }
          });
          if (res.ok) {
            window.location.reload();
          }
        });
      })();
    </script>
  `;

  return renderLayout({
    title: 'Reading Tracker',
    content,
    initialData: { books },
  });
}

function renderBookDetailPage(book, origin = '') {
  const isFinished = book.status === 'finished' || book.finished === true;
  const sharePath = `/books/${encodeURIComponent(book.id)}`;
  const shareUrl = origin ? `${origin}${sharePath}` : sharePath;

  const content = `
    <div style="margin-bottom: 1rem;">
      <a href="/" class="btn btn-secondary">&larr; Back to all books</a>
    </div>

    <article class="card" data-book-id="${escapeHtml(book.id)}">
      <div class="detail-meta">
        <span class="status-badge ${isFinished ? 'status-finished' : 'status-reading'}" id="book-status-badge">
          ${isFinished ? 'Finished' : 'Currently Reading'}
        </span>
        ${
          !isFinished
            ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" id="detail-finish-form" style="margin:0;">
                <button type="submit" class="btn btn-primary" id="detail-finish-btn">Mark as Finished</button>
              </form>`
            : ''
        }
      </div>

      <h1 id="book-title" style="margin-bottom: 0.25rem;">${escapeHtml(book.title)}</h1>
      <p id="book-author" class="book-author" style="font-size: 1.1rem; margin-bottom: 1.5rem;">by ${escapeHtml(book.author)}</p>

      <section aria-labelledby="notes-heading">
        <h2 id="notes-heading" style="font-size: 1.1rem;">My Notes</h2>
        <div id="book-notes" class="notes-box">${
          book.notes ? escapeHtml(book.notes) : '<em>No notes added yet.</em>'
        }</div>
      </section>

      <details style="margin-top: 1rem;">
        <summary style="cursor: pointer; font-weight: 600; color: var(--accent);">Edit Notes / Book Details</summary>
        <form id="edit-book-form" method="POST" action="/books/${encodeURIComponent(book.id)}/update" style="margin-top: 1rem;">
          <div class="form-group">
            <label for="edit-title">Title</label>
            <input type="text" id="edit-title" name="title" value="${escapeHtml(book.title)}" required />
          </div>
          <div class="form-group">
            <label for="edit-author">Author</label>
            <input type="text" id="edit-author" name="author" value="${escapeHtml(book.author)}" required />
          </div>
          <div class="form-group">
            <label for="edit-notes">Notes</label>
            <textarea id="edit-notes" name="notes">${escapeHtml(book.notes || '')}</textarea>
          </div>
          <button type="submit" class="btn btn-primary">Save Changes</button>
        </form>
      </details>

      <div class="share-bar">
        <label for="share-link" style="margin:0;">Share link:</label>
        <input type="text" id="share-link" class="share-input" readonly value="${escapeHtml(shareUrl)}" />
        <button type="button" id="copy-link-btn" class="btn btn-secondary">Copy Link</button>
        <span id="copy-feedback" class="toast" aria-live="polite"></span>
      </div>
    </article>

    <script>
      (function() {
        const shareInput = document.getElementById('share-link');
        if (shareInput && shareInput.value.startsWith('/')) {
          shareInput.value = window.location.origin + shareInput.value;
        }
        const copyBtn = document.getElementById('copy-link-btn');
        const feedback = document.getElementById('copy-feedback');
        if (copyBtn && shareInput) {
          copyBtn.addEventListener('click', async function() {
            try {
              if (navigator.clipboard && navigator.clipboard.writeText) {
                await navigator.clipboard.writeText(shareInput.value);
              } else {
                shareInput.select();
                document.execCommand('copy');
              }
              if (feedback) feedback.textContent = 'Copied!';
            } catch (err) {
              if (feedback) feedback.textContent = 'Press Ctrl+C to copy';
            }
          });
        }

        const finishForm = document.getElementById('detail-finish-form');
        if (finishForm) {
          finishForm.addEventListener('submit', async function(e) {
            if (!window.fetch) return;
            e.preventDefault();
            const res = await fetch('/api/books/${encodeURIComponent(book.id)}/finish', {
              method: 'POST',
              headers: { 'Accept': 'application/json' }
            });
            if (res.ok) {
