function renderNotFoundPage(message = 'Book not found') {
  const content = `
    <div class="card">
      <h1>404 - Not Found</h1>
      <p>${escapeHtml(message)}</p>
      <a href="/" class="btn btn-primary">Back to Reading List</a>
    </div>
  `;
  return renderLayout({ title: 'Not Found — Reading Tracker', content });
}

export function createApp({ filePath = process.env.BOOKS_FILE || DEFAULT_DATA_PATH, store } = {}) {
  const bookStore = store || new BookStore(filePath);

  const handler = async (req, res) => {
    try {
      const host = req.headers.host || 'localhost';
      const protocol = req.headers['x-forwarded-proto'] || 'http';
      const origin = `${protocol}://${host}`;
      const url = new URL(req.url || '/', origin);
      const pathname = url.pathname.replace(/\/+$/, '') || '/';
      const method = (req.method || 'GET').toUpperCase();
      const accept = (req.headers.accept || '').toLowerCase();
      const wantsJson =
        pathname.startsWith('/api/') ||
        accept.includes('application/json') && !accept.includes('text/html');

      // Health check
      if (pathname === '/api/health' && method === 'GET') {
        return sendJson(res, 200, { status: 'ok' });
      }

      // API: GET /api/books
      if (pathname === '/api/books' && method === 'GET') {
        const books = await bookStore.getAllBooks();
        const statusFilter = url.searchParams.get('status');
        if (statusFilter === 'reading') {
          return sendJson(
            res,
            200,
            books.filter((b) => b.status !== 'finished' && b.finished !== true)
          );
        }
        if (statusFilter === 'finished') {
          return sendJson(
            res,
            200,
            books.filter((b) => b.status === 'finished' || b.finished === true)
          );
        }
        return sendJson(res, 200, books);
      }

      // API: POST /api/books
      if (pathname === '/api/books' && method === 'POST') {
        const body = await parseBody(req);
        const created = await bookStore.addBook(body);
        return sendJson(res, 201, created);
      }

      // API: /api/books/:id/finish
      const apiFinishMatch = pathname.match(/^\/api\/books\/([^/]+)\/finish$/);
      if (apiFinishMatch && (method === 'POST' || method === 'PATCH' || method === 'PUT')) {
        const id = decodeURIComponent(apiFinishMatch[1]);
        const updated = await bookStore.markAsFinished(id);
        if (!updated) return sendJson(res, 404, { error: 'Book not found' });
        return sendJson(res, 200, updated);
      }

      // API: /api/books/:id
      const apiBookMatch = pathname.match(/^\/api\/books\/([^/]+)$/);
      if (apiBookMatch) {
        const id = decodeURIComponent(apiBookMatch[1]);
        if (method === 'GET') {
          const book = await bookStore.getBookById(id);
          if (!book) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 200, book);
        }
        if (method === 'PATCH' || method === 'PUT' || method === 'POST') {
          const body = await parseBody(req);
          const updated = await bookStore.updateBook(id, body);
          if (!updated) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 200, updated);
        }
        if (method === 'DELETE') {
          const deleted = await bookStore.deleteBook(id);
          if (!deleted) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 200, { deleted: true });
        }
      }

      // HTML / Form routes
      // Home page: GET /
      if ((pathname === '/' || pathname === '/books') && method === 'GET') {
        const books = await bookStore.getAllBooks();
        if (wantsJson) return sendJson(res, 200, books);
        return sendHtml(res, 200, renderHomePage(books));
      }

      // Form submission: POST /books (or POST /)
      if ((pathname === '/books' || pathname === '/') && method === 'POST') {
        const body = await parseBody(req);
        const created = await bookStore.addBook(body);
        if (wantsJson) return sendJson(res, 201, created);
        return redirect(res, '/');
      }

      // Form submission: POST /books/:id/finish (or /book/:id/finish)
      const htmlFinishMatch = pathname.match(/^\/books?\/([^/]+)\/finish$/);
      if (htmlFinishMatch && (method === 'POST' || method === 'PATCH' || method === 'PUT')) {
        const id = decodeURIComponent(htmlFinishMatch[1]);
        const updated = await bookStore.markAsFinished(id);
        if (!updated) {
          if (wantsJson) return sendJson(res, 404, { error: 'Book not found' });
          return sendHtml(res, 404, renderNotFoundPage());
        }
        if (wantsJson) return sendJson(res, 200, updated);
        const referer = req.headers.referer;
        if (referer && referer.includes(`/books/${encodeURIComponent(id)}`)) {
          return redirect(res, `/books/${encodeURIComponent(id)}`);
        }
        return redirect(res, '/');
      }

      // Form submission: POST /books/:id/update (or /book/:id/update)
      const htmlUpdateMatch = pathname.match(/^\/books?\/([^/]+)\/update$/);
      if (htmlUpdateMatch && (method === 'POST' || method === 'PATCH' || method === 'PUT')) {
        const id = decodeURIComponent(htmlUpdateMatch[1]);
        const body = await parseBody(req);
        const updated = await bookStore.updateBook(id, body);
        if (!updated) {
          if (wantsJson) return sendJson(res, 404, { error: 'Book not found' });
          return sendHtml(res, 404, renderNotFoundPage());
        }
        if (wantsJson) return sendJson(res, 200, updated);
        return redirect(res, `/books/${encodeURIComponent(id)}`);
      }

      // Single book page: GET /books/:id or GET /book/:id
      const htmlBookMatch = pathname.match(/^\/books?\/([^/]+)$/);
      if (htmlBookMatch) {
        const id = decodeURIComponent(htmlBookMatch[1]);
        if (method === 'GET') {
          const book = await bookStore.getBookById(id);
          if (!book) {
            if (wantsJson) return sendJson(res, 404, { error: 'Book not found' });
            return sendHtml(res, 404, renderNotFoundPage());
          }
          if (wantsJson) return sendJson(res, 200, book);
          return sendHtml(res, 200, renderBookDetailPage(book, origin));
        }
        if (method === 'POST' || method === 'PATCH' || method === 'PUT') {
          const body = await parseBody(req);
          const updated = await bookStore.updateBook(id, body);
          if (!updated) {
            if (wantsJson) return sendJson(res, 404, { error: 'Book not found' });
            return sendHtml(res, 404, renderNotFoundPage());
          }
          if (wantsJson) return sendJson(res, 200, updated);
          return redirect(res, `/books/${encodeURIComponent(id)}`);
        }
      }

      if (wantsJson) {
        return sendJson(res, 404, { error: 'Not found' });
      }
      return sendHtml(res, 404, renderNotFoundPage('Page not found'));
    } catch (err) {
      const status = err.statusCode || 500;
      const message = err.message || 'Internal Server Error';
      const accept = (req.headers.accept || '').toLowerCase();
      if ((req.url || '').startsWith('/api/') || accept.includes('application/json')) {
        return sendJson(res, status, { error: message });
      }
      return sendHtml(
        res,
        status,
        renderLayout({
          title: 'Error — Reading Tracker',
          content: `<div class="card"><h1>Error</h1><p>${escapeHtml(message)}</p><a href="/" class="btn btn-primary">Go Back</a></div>`,
        })
      );
    }
  };

  return {
    store: bookStore,
    handler,
    createServer() {
      return http.createServer(handler);
    },
  };
}

export function createServer(options = {}) {
  return createApp(options).createServer();
}

