function renderBookItem(book) {
  const isFinished = book.status === 'finished' || book.finished === true;
  const bookUrl = `/books/${encodeURIComponent(book.id)}`;
  return `<li class="book-item" data-book-id="${escapeHtml(book.id)}" data-status="${isFinished ? 'finished' : 'reading'}">
    <div class="book-info">
      <a href="${bookUrl}" class="book-title-link">${escapeHtml(book.title)}</a>
      <div class="book-author">by ${escapeHtml(book.author)}</div>
      ${
        book.notes
          ? `<p class="book-notes-preview">${escapeHtml(book.notes)}</p>`
          : ''
      }
    </div>
    <div class="book-actions">
      <span class="status-badge ${isFinished ? 'status-finished' : 'status-reading'}">
        ${isFinished ? 'Finished' : 'Currently Reading'}
      </span>
      ${
        !isFinished
          ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" class="finish-form" data-book-id="${escapeHtml(book.id)}" style="margin:0;">
              <button type="submit" class="btn btn-secondary finish-btn" data-book-id="${escapeHtml(book.id)}">Mark as Finished</button>
            </form>`
          : ''
      }
      <a href="${bookUrl}" class="btn btn-secondary">View</a>
    </div>
  </li>`;
}

function renderHomePage(books) {
  const currentlyReading = books.filter(
    (b) => b.status !== 'finished' && b.finished !== true
  );
  const finishedBooks = books.filter(
    (b) => b.status === 'finished' || b.finished === true
  );

  const content = `
    <section class="card" aria-labelledby="add-book-heading">
      <h2 id="add-book-heading">Add a Book</h2>
      <form id="add-book-form" method="POST" action="/books">
        <div class="form-grid">
          <div class="form-group">
            <label for="title">Title</label>
            <input type="text" id="title" name="title" required placeholder="e.g. The Left Hand of Darkness" />
          </div>
          <div class="form-group">
            <label for="author">Author</label>
            <input type="text" id="author" name="author" required placeholder="e.g. Ursula K. Le Guin" />
          </div>
          <div class="form-group full">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" placeholder="Thoughts, favorite quotes, or chapter notes..."></textarea>
          </div>
        </div>
        <button type="submit" class="btn btn-primary">Add Book</button>
      </form>
    </section>

    <section class="card" id="currently-reading-section" aria-labelledby="currently-reading-heading">
      <div class="section-header">
        <h2 id="currently-reading-heading" style="margin:0;">Currently Reading</h2>
        <span class="count-badge" id="reading-count">${currentlyReading.length}</span>
      </div>
      ${
        currentlyReading.length > 0
          ? `<ul class="book-list" id="currently-reading-list">${currentlyReading.map(renderBookItem).join('')}</ul>`
          : `<p class="empty-state" id="currently-reading-empty">No books currently being read.</p><ul class="book-list" id="currently-reading-list"></ul>`
      }
    </section>

    <section class="card" id="finished-section" aria-labelledby="finished-heading">
      <div class="section-header">
        <h2 id="finished-heading" style="margin:0;">Finished</h2>
        <span class="count-badge" id="finished-count">${finishedBooks.length}</span>
      </div>
      ${
        finishedBooks.length > 0
          ? `<ul class="book-list" id="finished-list">${finishedBooks.map(renderBookItem).join('')}</ul>`
          : `<p class="empty-state" id="finished-empty">No finished books yet.</p><ul class="book-list" id="finished-list"></ul>`
      }
    </section>

    <script>
      (function() {
        const addForm = document.getElementById('add-book-form');
        if (addForm) {
          addForm.addEventListener('submit', async function(e) {
            if (!window.fetch) return;
            e.preventDefault();
            const formData = new FormData(addForm);
            const payload = {
              title: formData.get('title'),
              author: formData.get('author'),
              notes: formData.get('notes') || ''
            };
            const res = await fetch('/api/books', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
              body: JSON.stringify(payload)
            });
            if (res.ok) {
              window.location.reload();
            }
          });
        }

        document.addEventListener('submit', async function(e) {
          const form = e.target.closest('.finish-form');
          if (!form || !window.fetch) return;
          e.preventDefault();
          const bookId = form.getAttribute('data-book-id');
          if (!bookId) return;
          const res = await fetch('/api/books/' + encodeURIComponent(bookId) + '/finish', {
            method: 'POST',
            headers: { 'Accept': 'application/json' }
          });
          if (res.ok) {
            window.location.reload();
          }
        });
      })();
    </script>
  `;

  return renderLayout({
    title: 'Reading Tracker',
    content,
    initialData: { books },
  });
}

