        <input type="text" id="share-link" class="share-input" readonly value="${escapeHtml(shareUrl)}" />
        <button type="button" id="copy-link-btn" class="btn btn-secondary">Copy Link</button>
        <span id="copy-feedback" class="toast" aria-live="polite"></span>
      </div>
    </article>

    <script>
      (function() {
        const shareInput = document.getElementById('share-link');
        if (shareInput && shareInput.value.startsWith('/')) {
          shareInput.value = window.location.origin + shareInput.value;
        }
        const copyBtn = document.getElementById('copy-link-btn');
        const feedback = document.getElementById('copy-feedback');
        if (copyBtn && shareInput) {
          copyBtn.addEventListener('click', async function() {
            try {
              if (navigator.clipboard && navigator.clipboard.writeText) {
                await navigator.clipboard.writeText(shareInput.value);
              } else {
                shareInput.select();
                document.execCommand('copy');
              }
              if (feedback) feedback.textContent = 'Copied!';
            } catch (err) {
              if (feedback) feedback.textContent = 'Press Ctrl+C to copy';
            }
          });
        }

        const finishForm = document.getElementById('detail-finish-form');
        if (finishForm) {
          finishForm.addEventListener('submit', async function(e) {
            if (!window.fetch) return;
            e.preventDefault();
            const res = await fetch('/api/books/${encodeURIComponent(book.id)}/finish', {
              method: 'POST',
              headers: { 'Accept': 'application/json' }
            });
            if (res.ok) {
              window.location.reload();
            }
          });
