        const editForm = document.getElementById('edit-book-form');
        if (editForm) {
          editForm.addEventListener('submit', async function(e) {
            if (!window.fetch) return;
            e.preventDefault();
            const formData = new FormData(editForm);
            const payload = {
              title: formData.get('title'),
