import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { createApp, createServer } from './src/app.js';
import { BookStore, DEFAULT_DATA_PATH } from './src/store.js';

export { createApp, createServer, BookStore, DEFAULT_DATA_PATH };

export function startServer({
  port = process.env.PORT ? Number(process.env.PORT) : 3000,
  host = process.env.HOST || '0.0.0.0',
  filePath = process.env.BOOKS_FILE || DEFAULT_DATA_PATH,
} = {}) {
  const app = createApp({ filePath });
  const server = app.createServer();
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => {
      const addr = server.address();
      const actualPort = typeof addr === 'object' && addr ? addr.port : port;
      console.log(`Reading Tracker running at http://localhost:${actualPort}`);
      resolve({ server, port: actualPort, store: app.store });
    });
  });
}

const isMain =
  process.argv[1] &&
  path.resolve(process.argv[1]) === path.resolve(fileURLToPath(import.meta.url));

if (isMain) {
  startServer().catch((err) => {
    console.error('Failed to start server:', err);
    process.exit(1);
  });
}

