import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { startServer } from '../server.js';
import { BookStore } from '../src/store.js';

describe('Reading Tracker Application', () => {
  let tmpDir;
  let booksFile;
  let serverInstance;
  let baseUrl;

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'reading-tracker-test-'));
    booksFile = path.join(tmpDir, 'books.json');
    const started = await startServer({ port: 0, host: '127.0.0.1', filePath: booksFile });
    serverInstance = started.server;
    baseUrl = `http://127.0.0.1:${started.port}`;
  });

  afterEach(async () => {
    if (serverInstance) {
      await new Promise((resolve) => serverInstance.close(resolve));
    }
    if (tmpDir) {
      await fs.rm(tmpDir, { recursive: true, force: true });
    }
  });

  it('renders home page with Currently Reading and Finished sections and add book form', async () => {
    const res = await fetch(`${baseUrl}/`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('Currently Reading');
    expect(html).toContain('Finished');
    expect(html).toContain('<form id="add-book-form"');
    expect(html).toContain('name="title"');
    expect(html).toContain('name="author"');
    expect(html).toContain('name="notes"');
  });

  it('adds a book via API and persists to JSON file across restarts', async () => {
    const createRes = await fetch(`${baseUrl}/api/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'Dune',
        author: 'Frank Herbert',
        notes: 'Fear is the mind-killer.',
      }),
    });
    expect(createRes.status).toBe(201);
    const createdBook = await createRes.json();
    expect(createdBook.id).toBeTruthy();
    expect(createdBook.title).toBe('Dune');
    expect(createdBook.author).toBe('Frank Herbert');
    expect(createdBook.notes).toBe('Fear is the mind-killer.');
    expect(createdBook.status).toBe('reading');
    expect(createdBook.finished).toBe(false);

    // Check JSON file on disk
    const rawFile = await fs.readFile(booksFile, 'utf8');
    const savedBooks = JSON.parse(rawFile);
    expect(savedBooks).toHaveLength(1);
    expect(savedBooks[0].title).toBe('Dune');

    // Simulate server restart with a new server instance reading the same file
    await new Promise((resolve) => serverInstance.close(resolve));
    const restarted = await startServer({ port: 0, host: '127.0.0.1', filePath: booksFile });
    serverInstance = restarted.server;
    baseUrl = `http://127.0.0.1:${restarted.port}`;

    const listRes = await fetch(`${baseUrl}/api/books`);
    expect(listRes.status).toBe(200);
    const booksAfterRestart = await listRes.json();
    expect(booksAfterRestart).toHaveLength(1);
    expect(booksAfterRestart[0].id).toBe(createdBook.id);
    expect(booksAfterRestart[0].title).toBe('Dune');
  });

  it('adds a book via HTML form submission and shows it under Currently Reading', async () => {
    const formBody = new URLSearchParams({
      title: 'Project Hail Mary',
      author: 'Andy Weir',
      notes: 'Amaze! Amaze!',
    });

    const postRes = await fetch(`${baseUrl}/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: formBody.toString(),
      redirect: 'manual',
    });
    expect(postRes.status).toBe(303);
    expect(postRes.headers.get('location')).toBe('/');

    const homeRes = await fetch(`${baseUrl}/`);
    const html = await homeRes.text();
    expect(html).toContain('Project Hail Mary');
    expect(html).toContain('Andy Weir');
    expect(html).toContain('Mark as Finished');
  });

  it('marks a book as finished and moves it to Finished section', async () => {
    const store = new BookStore(booksFile);
    const book = await store.addBook({
      title: 'Neuromancer',
      author: 'William Gibson',
      notes: 'The sky above the port was the color of television.',
    });

    // Mark finished via API
    const finishRes = await fetch(`${baseUrl}/api/books/${book.id}/finish`, {
      method: 'POST',
    });
    expect(finishRes.status).toBe(200);
    const finishedBook = await finishRes.json();
    expect(finishedBook.status).toBe('finished');
    expect(finishedBook.finished).toBe(true);
    expect(finishedBook.finishedAt).toBeTruthy();

    // Check home page reflects finished state
    const homeRes = await fetch(`${baseUrl}/`);
    const html = await homeRes.text();
    expect(html).toContain('Neuromancer');
    expect(html).toContain('data-status="finished"');
  });

  it('serves a direct shareable link for a single book with title, author, and notes', async () => {
    const store = new BookStore(booksFile);
    const book = await store.addBook({
      title: 'The Dispossessed',
      author: 'Ursula K. Le Guin',
      notes: 'An ambiguous utopia.',
    });

    // Home page has a link to /books/:id
    const homeRes = await fetch(`${baseUrl}/`);
    const homeHtml = await homeRes.text();
    expect(homeHtml).toContain(`/books/${book.id}`);

    // Direct request to the single book page
    const detailRes = await fetch(`${baseUrl}/books/${book.id}`);
    expect(detailRes.status).toBe(200);
    const detailHtml = await detailRes.text();
    expect(detailHtml).toContain('The Dispossessed');
    expect(detailHtml).toContain('Ursula K. Le Guin');
    expect(detailHtml).toContain('An ambiguous utopia.');
    expect(detailHtml).toContain(`/books/${book.id}`);

    // Return 404 for non-existent book
    const missingRes = await fetch(`${baseUrl}/books/non-existent-id`);
    expect(missingRes.status).toBe(404);
  });
});

